const text = $json.text ?? "";

if (!text.trim()) {
  return [];
}

const TAMANO = 1200;
const SOLAPAMIENTO = 200;

const chunks = [];

let inicio = 0;

while (inicio < text.length) {

  const fin = Math.min(inicio + TAMANO, text.length);

  const fragmento = text
    .slice(inicio, fin)
    .trim();

  if (fragmento) {
    chunks.push(fragmento);
  }

  if (fin >= text.length) {
    break;
  }

  inicio = fin - SOLAPAMIENTO;
}


return [{
  json: {
    chunks,
    cantidad_chunks: chunks.length,
    fuente: "MIDAGRI",
    tipo_documento: "boletin_diario",
    mercado: "MMF2",
    fecha: $("Loop Over Items").item.json.fecha_objetivo
  }
}];

const respuesta = $json;

const origen = $("Code - Preparar chunks Jina").item.json;

const chunks = origen.chunks ?? [];
const embeddings = respuesta.data ?? [];

const resultado = [];

for (let i = 0; i < embeddings.length; i++) {

  if (!chunks[i] || !embeddings[i]?.embedding) {
    continue;
  }

  resultado.push({
    json: {
      texto: chunks[i],

      embedding: embeddings[i].embedding,

      metadata: {
        fuente: "MIDAGRI",
        mercado: origen.mercado,
        tipo_documento: "boletin_diario",
        fecha: origen.fecha,
        chunk: i + 1,
        total_chunks: chunks.length,
        modelo_embedding: "jina-embeddings-v3",
        dimensiones: 384
      }
    }
  });
}

return resultado;

/*
 AGROSMART INSIGHTS - WF0 / WF1
 PARSER HISTORICO FLEXIBLE MMF2

 Fuente: MIDAGRI
 Mercado: Mercado Mayorista de Frutas N. 2

 Compatible con boletines historicos y actuales
 que conservan la estructura de columnas.

 REGLAS:
 - Identificar el origen del documento MMF2.
 - Validar la fecha real del PDF.
 - Reconocer encabezados variables.
 - Extraer productos y precios.
 - Conservar volumenes faltantes como null.
 - Omitir productos sin precio de hoy.
 - Evitar registros duplicados.
 - Detener registros con errores importantes.
*/

const items = $input.all();

const resultados = [];
const vistos = new Set();
const errores = [];
const omitidos = [];

const meses = {
  enero: 1,
  febrero: 2,
  marzo: 3,
  abril: 4,
  mayo: 5,
  junio: 6,
  julio: 7,
  agosto: 8,
  setiembre: 9,
  septiembre: 9,
  octubre: 10,
  noviembre: 11,
  diciembre: 12
};

// =======================================
// 1. FUNCIONES GENERALES
// =======================================

function normalizarTexto(valor) {
  return String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .toLowerCase()
    .trim();
}

function obtenerFecha() {

  const opciones = [
    () => $('Code - Validar fecha MMF2')
      .first().json.fecha_objetivo,

    () => $('Loop Over Items')
      .item.json.fecha_objetivo,

    () => $('Code - preparar fecha MIDAGRI1')
      .first().json.fecha_objetivo
  ];

  for (const opcion of opciones) {
    try {
      const fecha = String(opcion() ?? '')
        .slice(0, 10);

      if (/^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
        return fecha;
      }
    } catch (e) {}
  }

  throw new Error(
    'No se encontro fecha_objetivo de WF0 o WF1'
  );
}

const fechaObjetivo = obtenerFecha();

// =======================================
// 2. IDENTIFICAR ARCHIVO DE ORIGEN
// =======================================

function obtenerArchivoMMF2(item) {

  const candidatos = [];

  // Nombre conservado en el item actual.
  if (item.binary?.data?.fileName) {
    candidatos.push(item.binary.data.fileName);
  }

  if (item.json?.fileName) {
    candidatos.push(item.json.fileName);
  }

  // Buscar el archivo original descargado.
  try {
    const descarga = $('Descargar PDFs').first();

    if (descarga.binary?.data?.fileName) {
      candidatos.push(
        descarga.binary.data.fileName
      );
    }

    if (descarga.json?.fileName) {
      candidatos.push(
        descarga.json.fileName
      );
    }

    if (descarga.binary?.data?.url) {
      candidatos.push(
        descarga.binary.data.url
      );
    }

  } catch (e) {}

  // Identificar nombre del documento MMF2.
  const archivo = candidatos.find(valor =>
    /sisap-ingreso-mm2-[a-z0-9-]+\.pdf/i
      .test(String(valor))
  );

  return {
    archivo: archivo
      ? String(archivo)
      : '',

    archivoMMF2: Boolean(archivo)
  };
}

// =======================================
// 3. EXPRESIONES PARA EXTRAER FILAS
// =======================================

const num = String.raw`\d+(?:[.,]\d+)?`;

const celda = String.raw`(?:${num}|:|\.{3})`;

const unidad = String.raw`(Kilogramo|Bandeja|Caj[oó]n|Caja|Jaba|Bolsa|Ciento|Unidad|Saco|Paquete|Atado|Mano)`;

const patron = new RegExp(
  String.raw`^(.+?)\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  unidad + String.raw`\s+` +
  String.raw`(${num})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s*$`,
  'i'
);

// =======================================
// 4. CONVERTIR VALORES NUMERICOS
// =======================================

function numero(valor) {

  const texto = String(valor ?? '').trim();

  if (
    texto === '' ||
    texto === ':' ||
    texto === '...'
  ) {
    return null;
  }

  const valorNumerico = Number(
    texto.replace(',', '.')
  );

  return Number.isFinite(valorNumerico)
    ? valorNumerico
    : null;
}

// =======================================
// 5. EXTRAER UNA FILA
// =======================================

function extraerFila(textoFila) {

  const m = textoFila.match(patron);

  if (!m) {
    return null;
  }

  let producto = m[1]
    .replace(/\s+/g, ' ')
    .trim();

  // Limpiar encabezados que se unen al producto.
  producto = producto.replace(
    /^Ayer\s+Hoy\s+[ÚU]ltimos\s+7\s+d[ií]as\s+/i,
    ''
  );

  producto = producto.replace(
    /^Frutas\s+(?=Aguaje$)/i,
    ''
  );

  // Validar que sea un nombre de producto.
  if (
    producto.length < 2 ||
    producto.length > 90 ||
    /BOLET[IÍ]N|PRODUCTOS|PRECIO|MASA|FUENTE|ELABORACI[OÓ]N|MMF2|MIDAGRI|DGESEP|lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo/i
      .test(producto)
  ) {
    return null;
  }

  return {
    producto,

    volumen_ayer_t: numero(m[2]),
    volumen_t: numero(m[3]),
    volumen_promedio_7d_t: numero(m[4]),
    volumen_promedio_4d_t: numero(m[5]),

    unidad: m[6],
    equivalencia_kg: numero(m[7]),

    precio_ayer: numero(m[8]),
    precio: numero(m[9]),
    precio_promedio_7d: numero(m[10])
  };
}

// =======================================
// 6. PROCESAR LOS PDF
// =======================================

for (const item of items) {

  const texto = String(
    item.json.text ?? ''
  );

  if (!texto.trim()) {
    throw new Error(
      'Extract from File no entrego texto'
    );
  }

  const textoNormalizado =
    normalizarTexto(texto);

  const encabezadoNormalizado =
    normalizarTexto(texto.slice(0, 1500));

  // =====================================
  // 6.1 IDENTIFICAR EL MERCADO
  // =====================================

  const origen = obtenerArchivoMMF2(item);

  const encabezadoMMF2 =
    /\bmmf\s*2\b|\bmmf2\b/.test(
      encabezadoNormalizado
    ) ||

    /mercado\s+mayorista\s+(?:de\s+)?frutas/.test(
      encabezadoNormalizado
    ) ||

    /mercado\s+mayorista\s*n(?:ro|umero)?\s*2\b/.test(
      encabezadoNormalizado
    );

  const identidadMMF2 =
    origen.archivoMMF2 || encabezadoMMF2;

  console.log(
    'IDENTIFICACION MMF2',
    JSON.stringify({
      archivo: origen.archivo,
      archivo_mmf2: origen.archivoMMF2,
      encabezado_mmf2: encabezadoMMF2,
      identidad_mmf2: identidadMMF2
    })
  );

  // No aceptar documentos de origen desconocido.
  if (!identidadMMF2) {

    throw new Error(
      'No se pudo confirmar el origen MMF2. ' +
      'Archivo: ' +
      (origen.archivo || 'No identificado') +
      '. Revisar descarga y encabezado.'
    );
  }

  // =====================================
  // 6.2 VALIDACION FLEXIBLE DE ESTRUCTURA
  // =====================================

  const senales = {

    ingreso:
      /volumen\s+de\s+ingreso|masa\s+de\s+ingreso/i
        .test(textoNormalizado),

    precios:
      /precios?\s*(?:s\/|soles|mayoristas?)/i
        .test(textoNormalizado),

    unidadEquivalencia:
      /\bunidad\b[\s\S]{0,40}\bequiv/i
        .test(textoNormalizado),

    ayerHoy:
      /\bayer\b[\s\S]{0,40}\bhoy\b/i
        .test(textoNormalizado),

    promedios:
      /\bult(?:imos?)?\.?\s*[47]\b|\bpromedio\b/i
        .test(textoNormalizado)
  };

  const puntaje = Object.values(senales)
    .filter(Boolean)
    .length;

  // Separar las lineas del documento.
  const lineas = texto
    .split(/\r?\n/)
    .map(x =>
      x.replace(/\s+/g, ' ').trim()
    )
    .filter(Boolean);

  // Contar filas compatibles.
  let filasCompatibles = 0;

  for (
    let i = 0;
    i < lineas.length &&
    filasCompatibles < 3;
    i++
  ) {

    for (
      let k = 1;
      k <= Math.min(
        12,
        lineas.length - i
      );
      k++
    ) {

      const candidato = lineas
        .slice(i, i + k)
        .join(' ');

      if (extraerFila(candidato)) {
        filasCompatibles++;
        i += k - 1;
        break;
      }

      if (candidato.length > 190) {
        break;
      }
    }
  }

  console.log(
    'ESTRUCTURA MMF2',
    JSON.stringify({
      fecha_objetivo: fechaObjetivo,
      senales,
      puntaje,
      filas_compatibles: filasCompatibles
    })
  );

  // No depender de un unico encabezado.
  // Exigir columnas y filas reconocibles.
  if (
    puntaje < 2 ||
    filasCompatibles < 2
  ) {

    throw new Error(
      'Estructura MMF2 no reconocida. ' +
      'Puntaje: ' + puntaje +
      '. Filas compatibles: ' +
      filasCompatibles
    );
  }

  // =====================================
  // 6.3 VALIDAR FECHA REAL DEL PDF
  // =====================================

  const cabecera = texto.match(
    /\b(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|setiembre|septiembre|octubre|noviembre|diciembre)\s+de\s+(20\d{2})\b/i
  );

  if (!cabecera) {
    throw new Error(
      'No se pudo verificar la fecha del PDF'
    );
  }

  const fechaPDF =
    cabecera[3] + '-' +
    String(
      meses[cabecera[2].toLowerCase()]
    ).padStart(2, '0') + '-' +
    String(cabecera[1]).padStart(2, '0');

  if (fechaPDF !== fechaObjetivo) {

    throw new Error(
      'Fecha del PDF: ' + fechaPDF +
      '. Fecha solicitada: ' +
      fechaObjetivo
    );
  }

  // =====================================
  // 6.4 EXTRAER TODOS LOS PRODUCTOS
  // =====================================

  for (
    let i = 0;
    i < lineas.length;
    i++
  ) {

    let encontrado = null;
    let consumir = 0;

    for (
      let k = 1;
      k <= Math.min(
        12,
        lineas.length - i
      );
      k++
    ) {

      const candidato = lineas
        .slice(i, i + k)
        .join(' ');

      const fila =
        extraerFila(candidato);

      if (fila) {
        encontrado = fila;
        consumir = k;
        break;
      }

      if (candidato.length > 190) {
        break;
      }
    }

    if (!encontrado) {
      continue;
    }

    i += consumir - 1;

    const r = encontrado;

    // ===================================
    // CONTROL DE DUPLICADOS
    // ===================================

    const clave = [
      fechaPDF,
      normalizarTexto(r.producto),
      normalizarTexto(r.unidad)
    ].join('|');

    if (vistos.has(clave)) {
      continue;
    }

    vistos.add(clave);

    // ===================================
    // VALIDAR EQUIVALENCIA
    // ===================================

    if (
      r.equivalencia_kg === null ||
      r.equivalencia_kg <= 0
    ) {

      errores.push(
        'Equivalencia invalida: ' +
        r.producto
      );

      continue;
    }

    // ===================================
    // OMITIR PRECIO FALTANTE
    // ===================================

    if (r.precio === null) {

      omitidos.push({
        producto: r.producto,
        unidad: r.unidad,
        motivo: 'Sin precio de hoy'
      });

      continue;
    }

    if (
      !Number.isFinite(r.precio) ||
      r.precio <= 0
    ) {

      errores.push(
        'Precio invalido: ' +
        r.producto
      );

      continue;
    }

    // ===================================
    // VALIDAR VOLUMENES
    // ===================================

    const volumenes = [
      r.volumen_ayer_t,
      r.volumen_t,
      r.volumen_promedio_7d_t,
      r.volumen_promedio_4d_t
    ];

    if (
      volumenes.some(
        v => v !== null && v < 0
      )
    ) {

      errores.push(
        'Volumen negativo: ' +
        r.producto
      );

      continue;
    }

    // ===================================
    // REGISTRO VALIDO
    // ===================================

    resultados.push({
      json: {

        fecha: fechaPDF,

        codigo_cnpa: null,

        producto: r.producto,

        mercado: 'MMF2',

        unidad: r.unidad,

        equivalencia_kg:
          r.equivalencia_kg,

        precio: r.precio,

        precio_ayer: r.precio_ayer,

        precio_promedio_7d:
          r.precio_promedio_7d,

        volumen_t:
          r.volumen_t,

        volumen_kg:
          r.volumen_t === null
            ? null
            : r.volumen_t * 1000,

        volumen_ayer_t:
          r.volumen_ayer_t,

        volumen_promedio_7d_t:
          r.volumen_promedio_7d_t,

        volumen_promedio_4d_t:
          r.volumen_promedio_4d_t,

        fuente: 'MIDAGRI',

        formato_origen:
          'MMF2 independiente',

        tipo_prueba:
          'parser_mmf2_ingreso'
      }
    });
  }
}

// =======================================
// 7. CONTROL DE ERRORES
// =======================================

if (errores.length > 0) {

