/*
 AgroSmart - Validar fecha de PDF MMF2
 Compara fecha interna del boletin
 con la fecha solicitada por WF0.
*/

const items = $input.all();

const meses = {
  enero: 1,
  febrero: 2,
  marzo: 3,
  abril: 4,
  mayo: 5,
  junio: 6,
  julio: 7,
  agosto: 8,
  setiembre: 9,
  septiembre: 9,
  octubre: 10,
  noviembre: 11,
  diciembre: 12
};

const fechaObjetivo = String(
  $('Loop Over Items').first().json.fecha_objetivo ?? ''
).slice(0, 10);

if (!/^\d{4}-\d{2}-\d{2}$/.test(fechaObjetivo)) {
  throw new Error('Fecha objetivo invalida');
}

return items.map(item => {
  const texto = String(item.json.text ?? '');

  if (!texto.trim()) {
    return {
      json: {
        ...item.json,
        fecha_objetivo: fechaObjetivo,
        fecha_pdf: null,
        fecha_correcta: false,
        motivo: 'PDF sin texto extraible'
      }
    };
  }

  const cabecera = texto.match(
    /\b(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|setiembre|septiembre|octubre|noviembre|diciembre)\s+de\s+(20\d{2})\b/i
  );

  if (!cabecera) {
    return {
      json: {
        ...item.json,
        fecha_objetivo: fechaObjetivo,
        fecha_pdf: null,
        fecha_correcta: false,
        motivo: 'No se encontro fecha en el PDF'
      }
    };
  }

  const fechaPDF =
    cabecera[3] + '-' +
    String(meses[cabecera[2].toLowerCase()])
      .padStart(2, '0') + '-' +
    String(cabecera[1]).padStart(2, '0');

  const fechaCorrecta = fechaPDF === fechaObjetivo;

  return {
    json: {
      ...item.json,
      fecha_objetivo: fechaObjetivo,
      fecha_pdf: fechaPDF,
      fecha_correcta: fechaCorrecta,
      motivo: fechaCorrecta
        ? 'Fecha validada'
        : 'La fecha interna del PDF no coincide'
    }
  };
});

return $input.all().map(item => ({
  json: {
    fecha_objetivo: item.json.fecha_objetivo,
    fecha_pdf: item.json.fecha_pdf,
    mercado: 'MMF2',
    estado: 'OMITIDO',
    motivo: item.json.motivo
  }
}));

